begin;
do $$begin if public.get_stock_consistency_version()is distinct from '20261105-stock-consistency-1'then raise exception 'Verify Stock Consistency first.';end if;end;$$;
create or replace function greenloop_private.sc_is_bulk(q text)returns boolean language sql immutable set search_path=pg_catalog as $$select coalesce(btrim(q)~'^[0-9]{15}([[:space:],;]+[0-9]{15})+$',false);$$;
create or replace function greenloop_private.sc_query(h text,q text)returns boolean language sql immutable set search_path=pg_catalog as $$select case when greenloop_private.sc_is_bulk(q)then exists(select 1 from regexp_split_to_table(btrim(q),'[[:space:],;]+')x where strpos(coalesce(h,''),x)>0)else strpos(lower(coalesce(h,'')),lower(coalesce(q,'')))>0 end;$$;
revoke all on function greenloop_private.sc_is_bulk(text),greenloop_private.sc_query(text,text)from public,anon,authenticated;
create temporary table sc_search_review(identity text primary key)on commit drop;
