if strpos(s,'(length(s)>120 and not greenloop_private.sc_is_bulk(s))')=0 then if strpos(s,'length(s)>120')=0 then raise exception 'Reviewed bulk search boundary differs: %',id;end if;s:=replace(s,'length(s)>120','(length(s)>120 and not greenloop_private.sc_is_bulk(s))');end if;
execute s;insert into sc_search_review values(id::text)on conflict do nothing;end;$patch$;
do $seal$declare ids regprocedure[]:=array(select identity::regprocedure from sc_search_review);t record;begin
 update greenloop_private.office_routines set original_hash=md5(pg_get_functiondef(to_regprocedure(implementation))),wrapped_hash=md5(pg_get_functiondef(to_regprocedure(identity)))where to_regprocedure(identity)=any(ids)or to_regprocedure(implementation)=any(ids);
 update greenloop_private.capability_routines set original_hash=md5(pg_get_functiondef(to_regprocedure(implementation))),wrapped_hash=md5(pg_get_functiondef(to_regprocedure(identity)))where to_regprocedure(identity)=any(ids)or to_regprocedure(implementation)=any(ids);
 for t in select c.table_name,c.column_name hash_col,i.column_name id_col from information_schema.columns c join information_schema.columns i on i.table_schema=c.table_schema and i.table_name=c.table_name where c.table_schema='greenloop_private'and c.table_name like '%installation'and c.column_name in('hash','definition_hash')and i.column_name in('identity','object_identity','function_identity')loop execute format('update greenloop_private.%I set %I=md5(pg_get_functiondef(to_regprocedure(%I)))where to_regprocedure(%I)=any($1)',t.table_name,t.hash_col,t.id_col,t.id_col)using ids;end loop;
end;$seal$;
create table if not exists greenloop_private.stock_bulk_search_installation(identity text primary key,hash text not null);alter table greenloop_private.stock_bulk_search_installation enable row level security;revoke all on greenloop_private.stock_bulk_search_installation from public,anon,authenticated;
create or replace function public.get_stock_bulk_search_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_stock_consistency_version()='20261105-stock-consistency-1'and(select count(*)=24 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.stock_bulk_search_installation)then '20261105-stock-bulk-search-1'end;$$;
revoke all on function public.get_stock_bulk_search_version()from public;grant execute on function public.get_stock_bulk_search_version()to anon,authenticated;
insert into greenloop_private.stock_bulk_search_installation select identity,md5(pg_get_functiondef(identity::regprocedure))from sc_search_review on conflict(identity)do update set hash=excluded.hash;
insert into greenloop_private.stock_bulk_search_installation select x,md5(pg_get_functiondef(x::regprocedure))from unnest(array['greenloop_private.sc_query(text,text)','greenloop_private.sc_is_bulk(text)','public.get_stock_bulk_search_version()'])x on conflict(identity)do update set hash=excluded.hash;
do $$begin if public.get_stock_bulk_search_version()is distinct from '20261105-stock-bulk-search-1'then raise exception 'Bulk stock search verification failed. Nothing was installed.';end if;end;$$;
notify pgrst,'reload schema';commit;
select public.get_stock_bulk_search_version()installed_stock_bulk_search_version;
